import type { BankQuestion } from "@/lib/bank";

/** Cell Structure and Cell Division (Biology (NEET)): 100 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-cell-structure-division-1","question":"The fluid mosaic model of the plasma membrane was proposed by:","options":["Singer and Nicolson","Robert Brown","Schleiden and Schwann","Rudolf Virchow"],"answer":0,"explanation":"Singer and Nicolson proposed the fluid mosaic model in 1972: proteins float in a quasi-fluid lipid bilayer. Schleiden and Schwann gave the cell theory and Virchow added 'Omnis cellula-e cellula'.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-2","question":"The cell wall of fungi is chiefly made of:","options":["Cellulose","Peptidoglycan","Chitin","Pectin"],"answer":2,"explanation":"Fungal walls are made of chitin; plant walls of cellulose (with hemicellulose, pectin and proteins); bacterial walls of peptidoglycan.","difficulty":"easy"},
  {"id":"bio-cell-structure-division-3","question":"DNA replication takes place in which phase of the cell cycle?","options":["G₁ phase","G₂ phase","S phase","M phase"],"answer":2,"explanation":"In S (synthesis) phase DNA content doubles from 2C to 4C, but the chromosome number does not change; G₁ and G₂ are growth phases and M is division.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-4","question":"Crossing over between non-sister chromatids of homologous chromosomes occurs during:","options":["Leptotene","Zygotene","Pachytene","Diplotene"],"answer":2,"explanation":"Crossing over (mediated by recombinase) takes place at pachytene, when bivalents appear as tetrads. Zygotene is pairing (synapsis) and diplotene is when the chiasmata become visible as the synaptonemal complex dissolves.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-5","question":"Which of the following cell structures is NOT bounded by a membrane?","options":["Lysosome","Golgi cisterna","Peroxisome","Ribosome"],"answer":3,"explanation":"Ribosomes are non-membranous ribonucleoprotein particles (80S in eukaryotic cytoplasm, 70S in prokaryotes, mitochondria and chloroplasts). The other three are membrane-bound.","difficulty":"moderate"},
  {"id":"bio-cell-structure-division-6","question":"Mesosomes of bacteria are formed by:","options":["Extensions of the plasma membrane into the cell","Invagination of the outer membrane","Folding of the nuclear membrane","Fusion of ribosomes with the cell wall"],"answer":0,"explanation":"Mesosomes are extensions of the plasma membrane in the form of vesicles, tubules and lamellae; they help in cell wall formation, DNA replication and distribution, respiration and secretion.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-7","question":"The splitting of the centromere followed by movement of sister chromatids to opposite poles marks:","options":["Prophase","Metaphase","Anaphase","Telophase"],"answer":2,"explanation":"Anaphase begins when each centromere splits and the two chromatids, now daughter chromosomes, move to opposite poles with centromeres leading.","difficulty":"moderate"},
  {"id":"bio-cell-structure-division-8","question":"Gas vacuoles are found in:","options":["Amoeba","Blue-green, purple and green photosynthetic bacteria","All Gram-negative bacteria","Mycoplasma"],"answer":1,"explanation":"Among prokaryotic inclusion bodies, gas vacuoles occur in blue-green and in purple and green photosynthetic bacteria; phosphate, cyanophycean and glycogen granules are other inclusions.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-9","question":"Cells that exit the cycle and enter an inactive stage after G₁ are said to be in:","options":["G₀ phase","S phase","Interkinesis","G₂ phase"],"answer":0,"explanation":"G₀ (quiescent) cells are metabolically active but do not proliferate unless called upon; heart cells, for instance, do not divide at all.","difficulty":"moderate"},
  {"id":"bio-cell-structure-division-10","question":"In a human cell dividing in culture every 24 hours, what fraction of the cycle is roughly spent in M phase?","options":["About 50%","About 25%","About 4%","About 12%"],"answer":2,"explanation":"NCERT: a human cell cycle of about 24 h has an M phase of about 1 h, so cell division occupies roughly 1/24 ≈ 4% of the cycle; interphase takes over 95%.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-11","question":"Terminalisation of chiasmata, disappearance of the nucleolus and assembly of the meiotic spindle characterise:","options":["Diplotene","Metaphase I","Zygotene","Diakinesis"],"answer":3,"explanation":"Diakinesis, the last substage of prophase I, shows terminalisation of chiasmata, a fully condensed chromosome set, nucleolar disappearance and nuclear envelope breakdown; it is the transition to metaphase I.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-12","question":"In the membrane of a human erythrocyte, the approximate proportions of protein and lipid are:","options":["Protein 52%, lipid 40%","Protein 20%, lipid 75%","Protein 75%, lipid 20%","Protein 40%, lipid 52%"],"answer":0,"explanation":"Chemical analysis of the erythrocyte membrane shows about 52% protein and 40% lipid (NCERT). The ratio varies between cell types, with membrane proteins being either integral or peripheral.","difficulty":"hard","source":"NEET 2019 pattern"},
  {"id":"bio-cell-structure-division-13","question":"Which of the following is NOT a part of the endomembrane system?","options":["Lysosome","Golgi complex","Peroxisome","Endoplasmic reticulum"],"answer":2,"explanation":"The endomembrane system includes the ER, Golgi complex, lysosomes and vacuoles. Mitochondria, chloroplasts and peroxisomes are excluded because their functions are not coordinated with it.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-14","question":"The three parts of a bacterial flagellum are:","options":["Axoneme, basal body, hook","Filament, central sheath, hook","Filament, hook, basal body","Basal body, doublet, radial spoke"],"answer":2,"explanation":"A bacterial flagellum has a filament, a hook and a basal body; the filament is the longest portion and projects from the cell surface. Axoneme, doublets and radial spokes belong to eukaryotic cilia and flagella.","difficulty":"hard"},
  {"id":"bio-cell-structure-division-15","question":"Which statement about mitosis is INCORRECT?","options":["It is called equational division","It restores the nucleo-cytoplasmic ratio","Haploid cells of some lower plants and social insects divide by mitosis","It occurs only in diploid cells"],"answer":3,"explanation":"Mitosis is usually restricted to diploid somatic cells in animals, but haploid cells also divide mitotically in some lower plants and social insects (male honey bees), so 'only in diploid cells' is wrong.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-16","question":"A chromosome whose centromere lies slightly away from the middle, producing one shorter and one longer arm, is called:","options":["Sub-metacentric","Metacentric","Acrocentric","Telocentric"],"answer":0,"explanation":"Sub-metacentric: centromere slightly off-centre. Metacentric: middle, equal arms; acrocentric: near one end, one very short arm; telocentric: terminal centromere.","difficulty":"hard"},
  {"id":"bio-cell-structure-division-17","question":"The liquid endosperm of coconut is multinucleate because:","options":["Cytokinesis repeatedly occurred without karyokinesis","Karyokinesis was not followed by cytokinesis","Several nuclei fused after fertilisation","Meiosis produced many haploid nuclei in one cell"],"answer":1,"explanation":"When nuclear division (karyokinesis) is not followed by cytokinesis, a multinucleate condition, the syncytium, results, as in the liquid endosperm of coconut.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-18","question":"Which of the following best distinguishes a prokaryotic 70S ribosome from a eukaryotic cytoplasmic ribosome?","options":["70S is made of 60S and 40S subunits","70S ribosomes lack RNA","70S ribosomes occur only free in the cytoplasm, never attached","70S is made of 50S and 30S subunits"],"answer":3,"explanation":"Prokaryotic ribosomes are 70S (50S + 30S); eukaryotic cytoplasmic ribosomes are 80S (60S + 40S). S is the Svedberg sedimentation coefficient, which is why the subunits do not add arithmetically.","difficulty":"hard"},
  {"id":"bio-cell-structure-division-19","question":"How many of the following statements about mitochondria are correct?\n(i) The matrix contains a single circular DNA molecule and 70S ribosomes.\n(ii) The inner membrane forms infoldings called cristae.\n(iii) Mitochondria divide by fission.\n(iv) The outer membrane forms a continuous limiting boundary of the organelle.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are NCERT facts: circular DNA, few RNAs and 70S ribosomes in the matrix; cristae on the inner membrane; a continuous outer membrane; and fission as the mode of multiplication.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-20","question":"Match the substage of prophase I with its event.\nList I: (A) Zygotene (B) Pachytene (C) Diplotene (D) Diakinesis\nList II: (1) Dissolution of synaptonemal complex, chiasmata visible (2) Terminalisation of chiasmata (3) Formation of synaptonemal complex (4) Crossing over by recombinase","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":0,"explanation":"Zygotene: synapsis and synaptonemal complex; pachytene: crossing over; diplotene: complex dissolves and chiasmata appear; diakinesis: terminalisation of chiasmata.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-21","question":"Assertion (A): Lysosomes are described as suicide bags of the cell.\nReason (R): They are rich in hydrolytic enzymes capable of digesting carbohydrates, proteins, lipids and nucleic acids.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: lysosomes are Golgi-packaged vesicles of hydrolases (lipases, proteases, carbohydrases, active at acidic pH) which, if released, digest the cell's own contents.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-22","question":"How many of the following statements about the Golgi apparatus are correct?\n(i) Cisternae are 0.5 to 1.0 μm in diameter and stacked parallel to each other.\n(ii) The convex cis face is the forming face and the concave trans face is the maturing face.\n(iii) It is the site of formation of glycoproteins and glycolipids.\n(iv) It packages hydrolytic enzymes into lysosomes.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four statements are NCERT facts about the Golgi complex: cisternal size and stacking, the cis/trans faces, glycosylation and lysosome formation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-23","question":"Which statement about the plant cell wall is INCORRECT?","options":["The secondary wall is formed on the outer side of the primary wall","The middle lamella is made mainly of calcium pectate","The primary wall is capable of growth and diminishes as the cell matures","Plasmodesmata connect the cytoplasm of neighbouring cells"],"answer":0,"explanation":"The secondary wall is laid down on the inner side of the primary wall, towards the plasma membrane. The other three statements are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-24","question":"How many of the following are present in a prokaryotic cell: mesosome, nuclear envelope, ribosome, plasmid, endoplasmic reticulum?","options":["Only two","Only three","Only four","All five"],"answer":1,"explanation":"Prokaryotes have mesosomes, 70S ribosomes and plasmids but lack a nuclear envelope and all membrane-bound organelles including the ER. So three of five.","difficulty":"very-hard"},
  {"id":"bio-cell-structure-division-25","question":"In an organism with 2n = 16, the number of chromatids per cell at metaphase II of meiosis is:","options":["8","16","32","4"],"answer":1,"explanation":"Meiosis I halves the chromosome number to n = 8, but each chromosome still has two sister chromatids until anaphase II. So metaphase II shows 8 chromosomes = 16 chromatids. (At metaphase I it would be 16 chromosomes = 32 chromatids.)","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-26","question":"Which of the following correctly pairs the structure with its microtubule arrangement?","options":["Centriole: 9 + 2 doublets; axoneme: 9 + 0 triplets","Centriole: 9 + 2 triplets; axoneme: 9 + 0 doublets","Centriole: 9 + 0 triplets; axoneme: 9 + 2 doublets","Both centriole and axoneme: 9 + 2 doublets"],"answer":2,"explanation":"A centriole has nine peripheral triplet fibrils around a central hub (cartwheel, 9 + 0). The axoneme of cilia and flagella has nine peripheral doublets and one central pair (9 + 2).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-27","question":"Assertion (A): Metaphase is the best stage to study the morphology of chromosomes.\nReason (R): Complete disintegration of the nuclear envelope marks the start of metaphase and the chromosomes are then most condensed.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: by metaphase the envelope has gone, the chromosomes are fully condensed and spread on the metaphase plate, so their morphology is clearest.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-28","question":"How many of the following statements about meiosis are correct?\n(i) Homologous chromosomes separate in anaphase I while sister chromatids remain attached.\n(ii) Meiosis II is an equational division.\n(iii) Interkinesis is usually short-lived.\n(iv) DNA replicates once more between meiosis I and meiosis II.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. (iv) is false: there is no DNA replication during interkinesis; DNA replicates only once, before meiosis I.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-29","question":"Which statement about the nucleus is INCORRECT?","options":["The perinuclear space between the two nuclear membranes is 10 to 50 nm wide","Nuclear pores allow movement of RNA and proteins in both directions","The nucleolus is bounded by a single membrane and synthesises rRNA","Chromatin contains DNA, histones, non-histone proteins and RNA"],"answer":2,"explanation":"The nucleolus is NOT membrane-bound; it is a spherical structure in the nucleoplasm where ribosomal RNA is actively synthesised. The other three statements are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-30","question":"Match the cell or organelle with the correct size.\nList I: (A) Mycoplasma (B) Typical bacterium (C) Chloroplast length (D) Human red blood cell\nList II: (1) 7.0 μm (2) 5 to 10 μm (3) 0.3 μm (4) 1 to 2 μm","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"answer":0,"explanation":"Mycoplasma, the smallest cell, is about 0.3 μm; bacteria 1 to 2 μm; a chloroplast is 5 to 10 μm long and 2 to 4 μm wide; a human RBC is about 7.0 μm in diameter.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-31","question":"Rudolf Virchow (1855) modified the cell theory by stating that:","options":["All plants are composed of cells","Cells divide and new cells are formed from pre-existing cells (Omnis cellula-e cellula)","Life arises spontaneously from non-living matter","Cells contain a nucleus"],"answer":1,"explanation":"Schleiden and Schwann proposed the cell theory but did not explain how new cells form; Virchow added that new cells arise from pre-existing cells.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-32","question":"The ribosomes found in the stroma of chloroplasts are:","options":["90S, larger than cytoplasmic ribosomes","80S, the same as cytoplasmic ribosomes","Absent; chloroplasts have no ribosomes","70S, smaller than the 80S cytoplasmic ribosomes"],"answer":3,"explanation":"The chloroplast stroma contains small, double-stranded circular DNA and 70S ribosomes, which are smaller than the 80S cytoplasmic ribosomes of eukaryotes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-33","question":"Besides packaging materials, the Golgi apparatus is the important site of formation of:","options":["Steroid hormones only","Ribosomal RNA","ATP by oxidative phosphorylation","Glycoproteins and glycolipids"],"answer":3,"explanation":"Proteins synthesised on the RER are modified in the Golgi cisternae, which is the important site of formation of glycoproteins and glycolipids.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-34","question":"In plant cells, cytokinesis takes place by:","options":["Formation of a cell plate that grows from the centre towards the lateral walls","A furrow in the plasma membrane that deepens from the periphery inwards","Constriction of the cell wall from outside","Budding of the cell"],"answer":0,"explanation":"Plant cells are enclosed by a rigid wall, so a cell plate (the future middle lamella) forms in the centre and grows outwards. Furrowing occurs in animal cells.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-35","question":"In animal cells, lipid-like steroidal hormones are synthesised in the:","options":["Smooth endoplasmic reticulum","Nucleolus","Rough endoplasmic reticulum","Lysosomes"],"answer":0,"explanation":"The SER is the major site of lipid synthesis; in animal cells steroidal hormones are made there. The RER, bearing ribosomes, is active in protein synthesis and secretion.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-36","question":"Some chromosomes have non-staining secondary constrictions at a constant location, which give the appearance of a small fragment. This fragment is called the:","options":["Chromomere","Kinetochore","Centromere","Satellite"],"answer":3,"explanation":"A satellite is the small fragment seen beyond a secondary constriction. The kinetochore is a disc-shaped structure on the sides of the centromere (primary constriction).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-37","question":"A cell in G₁ has a DNA content of 2C. What is the DNA content of one cell at metaphase II of meiosis?","options":["2C","4C","8C","C"],"answer":0,"explanation":"DNA doubles in S phase (4C); meiosis I separates homologues, so each daughter cell has 2C (two chromatids per chromosome) at metaphase II. Gametes formed after meiosis II have C.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-38","question":"In the axoneme of a cilium or flagellum, the radial spokes connect:","options":["The two central microtubules to each other","One tubule of each peripheral doublet to the central sheath","The basal body to the plasma membrane","Adjacent peripheral doublets to one another"],"answer":1,"explanation":"The central tubules are joined by bridges and enclosed by a central sheath, which is linked to one tubule of each peripheral doublet by a radial spoke; peripheral doublets are joined to each other by linkers.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-39","question":"How many of the following statements about plastids are correct?\n(i) Chromoplasts contain fat-soluble carotenoid pigments such as carotene and xanthophylls.\n(ii) Amyloplasts store starch, as in potato.\n(iii) Elaioplasts store oils and fats, while aleuroplasts store proteins.\n(iv) The number of chloroplasts varies from one per cell in Chlamydomonas to 20–40 per cell in the mesophyll.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Leucoplasts are colourless plastids of varied shapes and sizes that store nutrients.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-40","question":"Match the stage of mitosis with its event.\nList I: (A) Prophase (B) Metaphase (C) Anaphase (D) Telophase\nList II: (1) Chromosomes cluster at opposite poles and the nuclear envelope reassembles (2) Chromosomal material condenses and the centrosomes move to opposite poles (3) Chromosomes align at the equatorial plate with spindle fibres attached to their kinetochores (4) Centromeres split and chromatids move to opposite poles","options":["A-2, B-4, C-3, D-1","A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4"],"answer":2,"explanation":"Condensation and centrosome movement mark prophase, alignment at the metaphase plate marks metaphase, splitting of centromeres marks anaphase, and re-formation of the nuclear envelope, nucleolus, Golgi and ER marks telophase.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-41","question":"Assertion (A): The plasma membrane is quasi-fluid in nature.\nReason (R): The lipid bilayer is held rigidly, so proteins cannot move laterally within it.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false: the quasi-fluid nature of the lipid lets proteins move laterally within the bilayer, which is important for cell growth, intercellular junctions, secretion, endocytosis and cell division.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-42","question":"How many of the following statements about the cell cycle are correct?\n(i) Interphase lasts more than 95% of the duration of the cell cycle.\n(ii) During S phase, the amount of DNA per cell doubles and the chromosome number also doubles.\n(iii) In animal cells, the centriole duplicates in the cytoplasm during S phase.\n(iv) During G₂ phase, proteins are synthesised in preparation for mitosis while cell growth continues.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (iii) and (iv) are correct. DNA doubles in S phase (2C to 4C) but the chromosome number stays the same (2n).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-43","question":"In an organism with 2n = 20, how many chromosomes (counted by centromeres) are present in a cell at anaphase of mitosis and in a cell at anaphase I of meiosis respectively?","options":["40 and 10","20 and 20","20 and 40","40 and 20"],"answer":3,"explanation":"At mitotic anaphase sister chromatids separate, so each becomes a chromosome: 40. At anaphase I homologues separate but sister chromatids stay joined, so the cell still has 20 centromeres.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-44","question":"Which of the following is NOT a significance of mitosis?","options":["It results in growth of multicellular organisms","It restores the nucleo-cytoplasmic ratio","It helps in cell repair, as in the upper layer of the epidermis and the lining of the gut","It increases genetic variability in the population"],"answer":3,"explanation":"Mitosis produces genetically identical diploid daughter cells. Increase in genetic variability is a significance of meiosis, through crossing over and independent assortment.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-45","question":"How many of the following statements are correct?\n(i) Ribosomes were first observed under the electron microscope as dense particles by George Palade in 1953.\n(ii) Ribosomes are bounded by a single membrane.\n(iii) The cytoskeleton, made of microtubules, microfilaments and intermediate filaments, is involved in mechanical support, motility and maintenance of cell shape.\n(iv) The 'S' in 70S is a direct measure of the mass of the ribosome.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iii) are correct. Ribosomes are non-membranous, and S (Svedberg unit) is a sedimentation coefficient that indirectly reflects density and size.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-46", "question": "The first person to see and describe a live cell was:", "options": ["Robert Hooke", "Anton von Leeuwenhoek", "Robert Brown", "Matthias Schleiden"], "answer": 1, "explanation": "Anton von Leeuwenhoek first saw and described a live cell. Robert Hooke described dead cork cells, and Robert Brown later discovered the nucleus.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-47", "question": "In animal cells, the centrosome usually contains:", "options": ["A single centriole surrounded by a nucleolus", "Two cylindrical centrioles lying perpendicular to each other", "Four centrioles arranged in a ring", "Two basal bodies joined by a cell plate"], "answer": 1, "explanation": "The centrosome is an organelle usually containing two cylindrical centrioles surrounded by amorphous pericentriolar material; the two centrioles lie perpendicular to each other.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-48", "question": "In some bacteria, small bristle-like fibres sprouting out of the cell that help them attach to rocks in streams and to host tissues are called:", "options": ["Pili", "Flagella", "Fimbriae", "Mesosomes"], "answer": 2, "explanation": "Fimbriae are small bristle-like fibres that help some bacteria attach to rocks and host tissues. Pili are elongated tubular structures made of a special protein, and flagella are for motility.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-49", "question": "Disc-shaped structures on the sides of the centromere, to which spindle fibres attach during cell division, are called:", "options": ["Kinetochores", "Chiasmata", "Satellites", "Telomeres"], "answer": 0, "explanation": "Every chromosome has a primary constriction, the centromere, on whose sides are disc-shaped kinetochores; the spindle fibres attach to them. Chiasmata are sites of crossing over seen in diplotene.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-50", "question": "Several ribosomes attached to a single mRNA, forming a chain that translates the mRNA, are called:", "options": ["Polysome", "Mesosome", "Microsome", "Nucleosome"], "answer": 0, "explanation": "Several ribosomes may attach to a single mRNA to form a polyribosome or polysome, which translates the mRNA into proteins. A nucleosome is DNA wrapped on a histone octamer.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-51", "question": "Interkinesis, the stage between meiosis I and meiosis II, is characterised by:", "options": ["Replication of DNA in a long S phase", "A short-lived stage with no replication of DNA", "Pairing of homologous chromosomes", "Formation of the synaptonemal complex"], "answer": 1, "explanation": "Interkinesis is generally short-lived and, unlike interphase, has no DNA replication; it is followed by prophase II, which is much simpler than prophase I.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-52", "question": "Bacteria are classified as Gram-positive or Gram-negative on the basis of:", "options": ["The presence or absence of a nucleus", "The type of ribosomes they carry", "Differences in their cell envelope and the way they respond to the Gram stain", "Whether they have flagella or not"], "answer": 2, "explanation": "Based on differences in the cell envelope and their response to Gram staining, bacteria that take up the stain are Gram positive and those that do not are Gram negative.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-53", "question": "The number of chloroplasts per cell varies from one per cell in ______ to ______ per cell in the mesophyll of leaves.", "options": ["Spirogyra; 5–10", "Chlamydomonas; 20–40", "Chlamydomonas; 100–200", "Volvox; 2–4"], "answer": 1, "explanation": "NCERT gives the range as 1 chloroplast per cell in the green alga Chlamydomonas to 20–40 per cell in leaf mesophyll. The other ranges are invented.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-54", "question": "Which statement about the plant vacuole is correct?", "options": ["It is bounded by a double membrane called the tonoplast", "It can occupy up to 90% of the volume of the cell, and the tonoplast transports ions into it against the concentration gradient", "Its ion concentration is always lower than that of the cytoplasm", "It contains mainly hydrolytic enzymes active at alkaline pH"], "answer": 1, "explanation": "The vacuole is bounded by a single membrane, the tonoplast, and can occupy up to 90% of a plant cell's volume. The tonoplast moves ions into the vacuole against the gradient, so their concentration in the vacuole is significantly higher than in the cytoplasm.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-55", "question": "In the oocytes of some vertebrates, which substage of prophase I can last for months or even years?", "options": ["Leptotene", "Zygotene", "Pachytene", "Diplotene"], "answer": 3, "explanation": "NCERT notes that diplotene can last for months or years in the oocytes of some vertebrates. Pachytene is the stage of crossing over, and leptotene and zygotene are short.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-56", "question": "The endoplasmic reticulum divides the intracellular space into two compartments. These are:", "options": ["Luminal (inside the ER) and extra luminal (cytoplasm)", "Cis and trans", "Matrix and intermembrane space", "Stroma and lumen"], "answer": 0, "explanation": "The ER divides the intracellular space into a luminal compartment (inside the ER) and an extra luminal compartment (the cytoplasm). Cis and trans are faces of the Golgi; matrix and intermembrane space belong to mitochondria.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-57", "question": "Many membrane-bound minute vesicles containing various enzymes, called microbodies, are present in:", "options": ["Only plant cells", "Only animal cells", "Both plant and animal cells", "Only prokaryotic cells"], "answer": 2, "explanation": "Microbodies, minute membrane-bound vesicles containing various enzymes, are present in both plant and animal cells. Prokaryotes lack membrane-bound organelles.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-58", "question": "The hydrolytic enzymes of lysosomes (lipases, proteases, carbohydrases) are optimally active at:", "options": ["Acidic pH", "Neutral pH", "Alkaline pH", "Any pH between 2 and 12"], "answer": 0, "explanation": "Lysosomal enzymes are optimally active at acidic pH. This is a frequent trap because many digestive enzymes of the small intestine work at alkaline pH.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-59", "question": "In animal cells, which event occurs in the cytoplasm during the S phase of the cell cycle?", "options": ["Formation of the spindle", "Duplication of the centriole", "Breakdown of the nuclear envelope", "Formation of the cell plate"], "answer": 1, "explanation": "While DNA replicates in the nucleus during S phase, the centriole duplicates in the cytoplasm of animal cells. Spindle formation and envelope breakdown are events of M phase.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-60", "question": "How many of the following statements about transport across the plasma membrane are correct?\n(i) Neutral solutes may move across the membrane by simple diffusion along the concentration gradient.\n(ii) Water moves across the membrane by diffusion, a process called osmosis.\n(iii) Polar molecules cannot pass through the non-polar lipid bilayer and need a carrier protein.\n(iv) The Na⁺/K⁺ pump moves ions against the concentration gradient using ATP.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Passive transport covers simple diffusion of neutral solutes and osmosis of water; polar molecules need carrier proteins, and active transport such as the Na⁺/K⁺ pump uses ATP to move ions against the gradient.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-61", "question": "Match the prokaryotic structure with its role.\nList I: (A) Pili (B) Plasmid (C) Mesosome (D) Glycocalyx\nList II: (1) Small circular extra-chromosomal DNA that may confer antibiotic resistance (2) Outer layer that may be a loose slime layer or a thick capsule (3) Elongated tubular structures made of a special protein (4) Infolding of the plasma membrane that helps in respiration, secretion and DNA distribution", "options": ["A-3, B-1, C-4, D-2", "A-1, B-3, C-2, D-4", "A-3, B-4, C-1, D-2", "A-2, B-1, C-4, D-3"], "answer": 0, "explanation": "Pili are tubular protein structures; plasmids are small circular DNA conferring traits such as antibiotic resistance; mesosomes are membrane infoldings aiding respiration, secretion and DNA distribution; the glycocalyx is a loose slime layer or a tough capsule.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-62", "question": "Assertion (A): Cells in the G₀ phase do not divide under normal conditions.\nReason (R): Cells in G₀ are metabolically inactive and can never be called back into the cell cycle.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: G₀ cells, such as many heart cells, do not proliferate. R is false: NCERT says G₀ cells remain metabolically active and can proliferate if called on to do so depending on the requirement of the organism.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-63", "question": "How many of the following statements about the cell cycle are correct?\n(i) G₁ is the interval between mitosis and the initiation of DNA replication.\n(ii) If a cell has 2n chromosomes in G₁, it still has 2n chromosomes after S phase.\n(iii) In G₂, proteins are synthesised in preparation for mitosis while cell growth continues.\n(iv) In animal cells the centriole duplicates during G₂.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Statements (i), (ii) and (iii) are correct. DNA doubles in S phase but the chromosome number does not change. Statement (iv) is wrong: the centriole duplicates in the cytoplasm during S phase, not G₂.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-64", "question": "A plant has 2n = 24. The number of bivalents at pachytene, the number of chromatids at metaphase I, and the number of chromosomes in each nucleus at telophase II are respectively:", "options": ["24, 48, 24", "12, 24, 12", "12, 48, 12", "12, 48, 24"], "answer": 2, "explanation": "24 chromosomes pair into 12 bivalents. Each chromosome has two chromatids after S phase, so metaphase I has 24 × 2 = 48 chromatids. After meiosis II each nucleus has n = 12 chromosomes.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-65", "question": "Arrange the following events of prophase I of meiosis in the correct order:\n(i) Dissolution of the synaptonemal complex\n(ii) Appearance of recombination nodules\n(iii) Synapsis of homologous chromosomes\n(iv) Terminalisation of chiasmata", "options": ["(iii), (ii), (i), (iv)", "(ii), (iii), (iv), (i)", "(iii), (i), (ii), (iv)", "(i), (iii), (ii), (iv)"], "answer": 0, "explanation": "Synapsis occurs in zygotene, recombination nodules appear in pachytene, the synaptonemal complex dissolves in diplotene, and chiasmata terminalise in diakinesis.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-66", "question": "Match the cell part with its description.\nList I: (A) Tonoplast (B) Nucleolus (C) Trans face of Golgi (D) Polysome\nList II: (1) Site of active ribosomal RNA synthesis (2) Membrane surrounding the vacuole (3) Several ribosomes on one mRNA (4) Maturing face of the Golgi apparatus", "options": ["A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-3, B-1, C-4, D-2", "A-4, B-1, C-2, D-3"], "answer": 1, "explanation": "The tonoplast surrounds the vacuole, the nucleolus is the site of active rRNA synthesis, the trans face is the maturing face of the Golgi, and a polysome is several ribosomes on one mRNA.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-67", "question": "Assertion (A): Plant cells undergo cytokinesis by forming a cell plate rather than by a cleavage furrow.\nReason (R): Plant cells are enclosed by a relatively inextensible cell wall.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Because the wall cannot be pinched in, new wall formation begins in the centre as a cell plate and grows outward to meet the existing lateral walls.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-68", "question": "How many of the following statements about chromosomes are correct?\n(i) A human somatic cell has 46 chromosomes.\n(ii) Every chromosome has a primary constriction, the centromere.\n(iii) An acrocentric chromosome has its centromere at the terminal end.\n(iv) At metaphase each chromosome consists of two sister chromatids held together by the centromere.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Statements (i), (ii) and (iv) are correct. Statement (iii) describes a telocentric chromosome; an acrocentric chromosome has its centromere close to the end, giving one extremely short and one very long arm.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-69", "question": "Which pair of cell type and shape is INCORRECTLY matched?", "options": ["Red blood cell — round and biconcave", "White blood cell — amoeboid", "Nerve cell — branched and long", "Mesophyll cell — columnar and ciliated"], "answer": 3, "explanation": "NCERT shows RBCs as round and biconcave, WBCs as amoeboid and nerve cells as branched and long. Mesophyll cells are round or oval, not columnar and ciliated, so this pair is wrong.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-70", "question": "Which statement about mitochondria and chloroplasts is INCORRECT?", "options": ["Both are double-membrane-bound organelles", "Both contain their own small circular DNA", "Both have 70S ribosomes in their matrix or stroma", "Both arise only from the Golgi apparatus"], "answer": 3, "explanation": "Mitochondria and chloroplasts are double-membrane-bound, contain circular DNA and 70S ribosomes, and divide by fission. They do not arise from the Golgi, which is the incorrect statement.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-71","question":"Normal mature erythrocytes of many mammals and the sieve tube cells of vascular plants lack a:","options":["Plasma membrane","Cytoplasm","Nucleus","Lipid bilayer"],"answer":2,"explanation":"These cells lose their nucleus as they mature but keep their plasma membrane and cytoplasm.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-72","question":"In Amoeba, the contractile vacuole is important for:","options":["Excretion and osmoregulation","Digestion of food","Locomotion","Photosynthesis"],"answer":0,"explanation":"The contractile vacuole removes excess water and wastes. Food vacuoles, formed by engulfing food particles, carry out digestion.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-73","question":"Yeast can progress through the cell cycle in only about:","options":["24 hours","12 hours","10 minutes","90 minutes"],"answer":3,"explanation":"A yeast cell completes a cell cycle in about 90 minutes, whereas a typical human cell in culture takes about 24 hours.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-74","question":"The material of the nucleus that stains with basic dyes was named chromatin by:","options":["Robert Brown","George Palade","Camillo Golgi","Flemming"],"answer":3,"explanation":"Flemming coined the term chromatin. Robert Brown discovered the nucleus, Golgi described the Golgi apparatus, and Palade first saw ribosomes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-75","question":"Schwann (1839), from his studies on plant tissues, concluded that a unique character of plant cells is the presence of the:","options":["Cell wall","Nucleus","Vacuole","Mitochondria"],"answer":0,"explanation":"Schwann reported that cells have a thin outer layer, now called the plasma membrane, and that the cell wall is unique to plant cells.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-76","question":"During the G2 phase of the cell cycle:","options":["DNA is replicated","The cell exits the cycle and becomes quiescent","Proteins are synthesised in preparation for mitosis while cell growth continues","The sister chromatids separate"],"answer":2,"explanation":"In G2, proteins needed for mitosis are made and the cell keeps growing. DNA replication happens in S phase, quiescence is G0, and chromatids separate at anaphase.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-77","question":"In plants, mitotic divisions that allow continuous growth throughout life occur in the:","options":["Mature xylem vessels","Sieve tubes","Cork cells","Meristematic tissues: the apical and lateral cambium"],"answer":3,"explanation":"Mitosis in apical and lateral meristems lets plants grow throughout their life. Mature xylem vessels and cork cells are dead, and sieve tubes have no nucleus.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-78","question":"Which of the following is NOT a function of the plant cell wall?","options":["Giving shape to the cell","Protecting the cell from mechanical damage and infection","Helping in cell-to-cell interaction","Synthesising proteins"],"answer":3,"explanation":"The cell wall gives shape, protects the cell, helps in cell-to-cell interaction and keeps out undesirable macromolecules. Proteins are synthesised by ribosomes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-79","question":"Larger and more numerous nucleoli are present in cells that are:","options":["Actively carrying out protein synthesis","In the G0 (quiescent) stage","Dead, such as cork cells","Mature erythrocytes"],"answer":0,"explanation":"The nucleolus is the site of active ribosomal RNA synthesis, so cells making a lot of protein have larger and more numerous nucleoli.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-80","question":"In some prokaryotes such as cyanobacteria, membranous extensions into the cytoplasm that contain pigments are called:","options":["Mesosomes","Plasmids","Chromatophores","Fimbriae"],"answer":2,"explanation":"Chromatophores carry photosynthetic pigments. Mesosomes are infoldings involved in wall formation, DNA distribution and respiration, plasmids are extra DNA, and fimbriae help in attachment.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-81","question":"Phosphate granules, cyanophycean granules and glycogen granules in prokaryotic cells are:","options":["Membrane-bound vacuoles","Small circular DNA molecules","Parts of the mesosome","Inclusion bodies that store reserve material, not bound by any membrane"],"answer":3,"explanation":"Reserve material in prokaryotes is stored as inclusion bodies, which have no membrane and lie free in the cytoplasm.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-82","question":"The cell wall of algae is made of:","options":["Chitin and peptidoglycan","Cellulose, hemicellulose, pectins and proteins only","Murein only","Cellulose, galactans, mannans and minerals such as calcium carbonate"],"answer":3,"explanation":"Algal cell walls contain cellulose, galactans, mannans and minerals such as calcium carbonate. Other plants have walls of cellulose, hemicellulose, pectins and proteins.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-83","question":"A typical mitochondrion is sausage-shaped or cylindrical, with a:","options":["Diameter of 0.2 to 1.0 µm and length of 1.0 to 4.1 µm","Diameter of 2 to 4 µm and length of 5 to 10 µm","Diameter of 15 to 20 nm","Diameter of 5 to 10 µm and length of 20 to 40 µm"],"answer":0,"explanation":"Mitochondria are 0.2 to 1.0 µm wide (about 0.5 µm on average) and 1.0 to 4.1 µm long. A width of 2 to 4 µm and length of 5 to 10 µm describes a chloroplast.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-84","question":"The size of a prokaryotic 70S ribosome, made of 50S and 30S subunits, is about:","options":["15 nm by 20 nm","0.5 µm by 1 µm","2 µm by 4 µm","150 nm by 200 nm"],"answer":0,"explanation":"Prokaryotic ribosomes measure about 15 nm by 20 nm, far too small to be seen under a light microscope.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-85","question":"At telophase I of meiosis, the nuclear membrane and nucleolus reappear and cytokinesis follows. The result is a:","options":["Tetrad of cells","Bivalent","Syncytium","Dyad of cells"],"answer":3,"explanation":"Telophase I with cytokinesis gives a dyad of cells; meiosis II then gives a tetrad. A bivalent is a pair of synapsed homologous chromosomes.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-86","question":"Which statement about meiosis II is correct?","options":["It is preceded by DNA replication during interkinesis","Homologous chromosomes pair during its prophase","It begins immediately after cytokinesis, usually before the chromosomes have fully elongated","Crossing over takes place during its prophase"],"answer":2,"explanation":"Meiosis II starts right after cytokinesis and resembles a normal mitosis. Interkinesis has no DNA replication, and pairing and crossing over happen only in prophase I.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-87","question":"A cell in G1 has 14 chromosomes and a DNA content of 2C. After the S phase, in G2, it will have:","options":["28 chromosomes and 4C DNA","14 chromosomes and 4C DNA","14 chromosomes and 2C DNA","28 chromosomes and 2C DNA"],"answer":1,"explanation":"DNA doubles in S phase, but each chromosome now has two sister chromatids joined at one centromere, so the chromosome number stays 14.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-88","question":"In an animal cell, the centrosome, which was duplicated during interphase, begins to move towards the opposite poles of the cell during:","options":["Prophase","Metaphase","Anaphase","Telophase"],"answer":0,"explanation":"In prophase the two centrosomes move to opposite poles, each radiating asters, and together with the spindle fibres they form the mitotic apparatus.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-89","question":"At the end of mitotic prophase, a cell viewed under the microscope no longer shows the:","options":["Chromosomes","Centrosomes","Golgi complexes, endoplasmic reticulum, nucleolus and nuclear envelope","Plasma membrane"],"answer":2,"explanation":"By the end of prophase the Golgi complexes, ER, nucleolus and nuclear envelope have disappeared from view, while the condensed chromosomes become clearer.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-90","question":"From the following list, how many are functions of mesosomes?\nCell wall formation; DNA replication and distribution to daughter cells; respiration; secretion; increasing the surface area and enzymatic content of the plasma membrane; storage of photosynthetic pigments; attachment to host tissues","options":["Three","Four","Five","Six"],"answer":2,"explanation":"The first five are functions of mesosomes. Pigments are held in chromatophores, and attachment to rocks or host tissues is the job of fimbriae.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-91","question":"An organism has 2n = 8. How many chromosomes (counted by centromeres) are present in each cell at anaphase II of meiosis?","options":["4","8","16","2"],"answer":1,"explanation":"After meiosis I each cell has 4 chromosomes, each with two chromatids. At anaphase II the centromeres split, so each cell briefly has 8 chromosomes, 4 moving to each pole.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-92","question":"A single cell divides by mitosis, and all its daughter cells keep dividing synchronously until there are 64 cells. How many generations of division, and how many individual mitotic divisions in total, have taken place?","options":["6 and 64","6 and 63","64 and 63","32 and 6"],"answer":1,"explanation":"2 to the power 6 = 64, so there are six generations. The total number of divisions is 1 + 2 + 4 + 8 + 16 + 32 = 63, since each division adds one cell.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-93","question":"If every product of meiosis is functional, how many diploid meiocytes must undergo meiosis to form 100 haploid cells?","options":["100","50","25","200"],"answer":2,"explanation":"Each meiocyte gives four haploid cells after meiosis I and II, so 100 / 4 = 25 meiocytes are needed.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-94","question":"From the following list, how many are present in plant cells but absent from animal cells?\nCell wall, plastids, large central vacuole, centrioles, Golgi apparatus, mitochondria","options":["Two","Four","Three","Five"],"answer":2,"explanation":"Cell wall, plastids and a large central vacuole are found in plant cells but not in animal cells. Centrioles are found in animal cells and are absent in almost all plant cells; Golgi and mitochondria are found in both.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-95","question":"Assertion (A): Meiosis conserves the specific chromosome number of each species across generations in sexually reproducing organisms.\nReason (R): Meiosis halves the chromosome number in the gametes, and fertilisation restores the diploid number.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. Meiosis paradoxically reduces the chromosome number by half, and this is exactly what keeps the number constant once fertilisation restores it; R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-96","question":"How many of the following statements about the prokaryotic cell envelope are correct?\n(i) In most prokaryotes it is a tightly bound three-layered structure: glycocalyx, cell wall and plasma membrane.\n(ii) The glycocalyx may be a loose slime layer in some bacteria and a thick, tough capsule in others.\n(iii) Although each layer has a distinct function, the three layers act together as a single protective unit.\n(iv) The cell wall determines the shape of the cell and stops the bacterium from bursting or collapsing.\n(v) Mycoplasma has a particularly thick cell wall.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. Mycoplasma has no cell wall at all.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-97","question":"Match the stage of meiosis with its event.\nList I: (A) Metaphase I (B) Anaphase I (C) Metaphase II (D) Anaphase II\nList II: (1) Centromeres split, and sister chromatids move to opposite poles (2) Bivalents align on the equatorial plate, with microtubules from opposite poles attached to the pair of homologous chromosomes (3) Homologous chromosomes separate while sister chromatids stay together at their centromeres (4) Chromosomes align, with microtubules from opposite poles attached to the kinetochores of sister chromatids","options":["A-2, B-1, C-4, D-3","A-4, B-3, C-2, D-1","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"In meiosis I the homologous pairs line up and then separate. In meiosis II single chromosomes line up with each sister kinetochore facing a pole, and the centromeres split at anaphase II.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-98","question":"From the following list, how many structures are bounded by a double membrane?\nNucleus, mitochondrion, chloroplast, lysosome, vacuole, Golgi body, endoplasmic reticulum, ribosome","options":["Two","Three","Four","Five"],"answer":1,"explanation":"The nucleus, mitochondria and chloroplasts have double membranes. Lysosomes, vacuoles, Golgi and ER have single membranes, and ribosomes have none.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-99","question":"Assertion (A): Cells of the upper layer of the epidermis, cells of the lining of the gut and blood cells are constantly replaced by mitosis.\nReason (R): Mitosis restores the nucleo-cytoplasmic ratio of a growing cell.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true and both are significances of mitosis, but cell repair (A) is not explained by the restoring of the nucleo-cytoplasmic ratio (R).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-100","question":"From the following list, how many events occur in meiosis but NOT in mitosis?\nSynapsis, crossing over, formation of chiasmata, separation of homologous chromosomes, splitting of centromeres, condensation of chromosomes, formation of a spindle","options":["Three","Four","Five","Six"],"answer":1,"explanation":"Synapsis, crossing over, chiasma formation and separation of homologues happen only in meiosis I. Centromere splitting, chromosome condensation and spindle formation happen in both divisions.","difficulty":"very-hard","source":"NEET pattern"},
];

export default questions;
